func (c *Cache) Get(ctx context.Context, k string) (Profile, error) {
    c.mu.RLock()
    p, ok := c.data[k]
    c.mu.RUnlock()
    if ok {
        return p, nil
    }
    v, err, _ := c.sf.Do(k, func() (any, error) {
        return c.load(ctx, k)
    })
    if err != nil {
        return Profile{}, err
    }
    p = v.(Profile)
    c.mu.Lock()
    c.data[k] = p
    c.mu.Unlock()
    return p, nil
}
